785	  /**
786	   * Re-derive and re-seed the CURRENT depth's writeKey (73-07 Task 1, supplier
787	   * for plan 73-08's SC4 `refreshWriteAccess`).
788	   *
789	   * At the share ROOT, the writeKey source is `resolveSharedRootWriteKey`
790	   * over the grant's `encryptedWriteKey` -- this never depends on transient
791	   * per-depth SDK state, so it is always cleanly re-derivable here.
792	   *
793	   * At a DEEPER depth, `resolveSharedSubfolderWriteKey` requires the PARENT
794	   * depth to be the one currently seeded into the SDK's `sharedFolderTree`
795	   * (it reads `sharedFolderTree.get(shareId)`) -- but the depth seeded at
796	   * this call site is the CURRENT (child) depth, not its parent, so a clean
797	   * re-derivation is not reproducible from here. Falls back to re-seeding
798	   * from the retained `currentWriteKeyRef` (this depth's last-known-good
799	   * writeKey) instead of re-walking the write-chain from an unavailable
800	   * parent context.
801	   */
802	  const refreshCurrentDepthWriteKey = useCallback(async () => {
803	    const currentShareId = p.currentShareId;
804	    const currentIpnsName = p.ipnsName;
805	    const currentFolderKey = p.folderKey;
806	    if (!currentShareId || !currentIpnsName || !currentFolderKey) return;
807	    const shareEntry = p.sharedItems.find((s) => s.share.shareId === currentShareId);
808	    if (!shareEntry) return;
809	    const auth = useAuthStore.getState();
810	    if (!auth.vaultKeypair) return;
811	    const vaultKeypair = auth.vaultKeypair;
812	
813	    const isRootDepth = currentIpnsName === shareEntry.share.ipnsName;
814	    let refreshedWriteKey: Uint8Array | null = null;
815	
816	    if (isRootDepth) {
817	      let freshWriteKey: Uint8Array | null = null;
818	      try {
819	        freshWriteKey = await resolveSharedRootWriteKey(
820	          shareEntry.share.encryptedWriteKey,
821	          vaultKeypair.privateKey
822	        );
823	        refreshedWriteKey = freshWriteKey ? new Uint8Array(freshWriteKey) : null;
824	      } catch (err) {
825	        logger.error('[SharedNav] Failed to refresh root write key:', err);
826	      } finally {
827	        // D-09: this call's own derived buffer is the terminal owner once
828	        // cloned into refreshedWriteKey above.
829	        freshWriteKey?.fill(0);
830	      }
831	    } else {
832	      // See doc comment above: a deeper re-derivation needs the PARENT depth
833	      // seeded, not reproducible here -- fall back to the retained buffer.
834	      // Cloned (not read live) so the subsequent zeroWriteKey() below cannot
835	      // zero this snapshot out from under itself (same underlying buffer).
836	      refreshedWriteKey = p.currentWriteKeyRef.current
837	        ? new Uint8Array(p.currentWriteKeyRef.current)
838	        : null;
